def adj(u,v):
 if u==v:return False
 u,v=sorted((u,v))
 if v<4:return True
 if u<4 and v<8:return True
 if u>=4 and v<8:return (u,v) in [(4,5),(6,7)]
 if u<4 and v>=8:return (u<2)==(v>=10)
 return False
rows=[]
